Definition u32_eq_zero_derive_fp_by_base := 
forall (a_pre: Z) (A_fp: Z) ,
  (store_fp a_pre A_fp )
|--
EX (A_base: Z) ,
  ((store_u256 a_pre A_base ))
  **
  (((EX retval_2,
  “ (0 <= retval_2) ” 
  &&  “ (retval_2 <= 1) ” 
  &&  “ (retval_2 = 1) ” 
  &&  “ (A_base = 0) ”
  &&  (store_u256 a_pre A_base ))
  ||
  (EX retval_2,
  “ (0 <= retval_2) ” 
  &&  “ (retval_2 <= 1) ” 
  &&  “ (retval_2 = 0) ” 
  &&  “ (A_base <> 0) ”
  &&  (store_u256 a_pre A_base )))
  -*
  ((EX retval,
  “ (0 <= retval) ” 
  &&  “ (retval <= 1) ” 
  &&  “ (retval = 1) ” 
  &&  “ (A_fp = 0) ”
  &&  (store_fp a_pre A_fp ))
  ||
  (EX retval,
  “ (0 <= retval) ” 
  &&  “ (retval <= 1) ” 
  &&  “ (retval = 0) ” 
  &&  “ (A_fp <> 0) ”
  &&  (store_fp a_pre A_fp ))))
.

Definition u32_eq_derive_fp_by_base := 
forall (b_pre: Z) (a_pre: Z) (B_fp: Z) (A_fp: Z) ,
  (store_fp a_pre A_fp )
  **  (store_fp b_pre B_fp )
|--
EX (A_base: Z) (B_base: Z) ,
  ((store_u256 a_pre A_base )
  **  (store_u256 b_pre B_base ))
  **
  (((EX retval_2,
  “ (0 <= retval_2) ” 
  &&  “ (retval_2 <= 1) ” 
  &&  “ (retval_2 = 1) ” 
  &&  “ (A_base = B_base) ”
  &&  (store_u256 a_pre A_base )
  **  (store_u256 b_pre B_base ))
  ||
  (EX retval_2,
  “ (0 <= retval_2) ” 
  &&  “ (retval_2 <= 1) ” 
  &&  “ (retval_2 = 0) ” 
  &&  “ (A_base <> B_base) ”
  &&  (store_u256 a_pre A_base )
  **  (store_u256 b_pre B_base )))
  -*
  ((EX retval,
  “ (0 <= retval) ” 
  &&  “ (retval <= 1) ” 
  &&  “ (retval = 1) ” 
  &&  “ (A_fp = B_fp) ”
  &&  (store_fp a_pre A_fp )
  **  (store_fp b_pre B_fp ))
  ||
  (EX retval,
  “ (0 <= retval) ” 
  &&  “ (retval <= 1) ” 
  &&  “ (retval = 0) ” 
  &&  “ (A_fp <> B_fp) ”
  &&  (store_fp a_pre A_fp )
  **  (store_fp b_pre B_fp ))))
.

